// What happens when you click something.
//
// One interaction, on purpose: pressing the button picks a new accent colour, and
// everything using --accent changes at once because styles.css names that colour in
// exactly one place.
//
// Nothing here talks to the internet.

const FACTS = [
  "The word dinosaur means 'terrible lizard,' although dinosaurs were not actually lizards.",
  "Birds are living dinosaurs. They are the only dinosaur group still alive today.",
  "Some dinosaur fossils show feathers, including fossils of several meat-eating dinosaurs.",
  "A Triceratops had three horns and a large shield called a frill."
];

const button = document.getElementById("surprise");
const fact = document.getElementById("fact");

button.addEventListener("click", () => {
  const pick = FACTS[Math.floor(Math.random() * FACTS.length)];
  fact.textContent = pick;
});

