/* How the page looks.
 *
 * The colours are named once here and used everywhere below, so changing one line
 * changes the whole site. Try it: change --accent and reload the preview.
 *
 * No web fonts and no downloaded stylesheets. This page works with the Wi-Fi off.
 */

:root {
  --bg: #f8f1df;
  --ink: #25352a;
  --muted: #637064;
  --accent: #c65d36;
  --card: #fffdf6;
  --line: #d9cbaa;
  --radius: 18px;
}

/* Respects the setting on the computer rather than guessing. */
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #1d2922;
    --ink: #f5efd9;
    --muted: #c4c7ae;
    --accent: #f08a58;
    --card: #29382d;
    --line: #49604d;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  /* The fonts already on the computer. Nothing is downloaded. */
  font-family: system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
  font-size: 17px;
  line-height: 1.6;
  color: var(--ink);
  background: var(--bg);
}

.site-header,
.site-nav,
main,
.site-footer {
  /* Keeps a line of text a comfortable length however wide the window is. */
  max-width: 44rem;
  margin: 0 auto;
  padding: 0 1.25rem;
}

.site-header {
  position: relative;
  margin-top: 1.25rem;
  padding: 2.25rem 1.5rem 2rem;
  overflow: hidden;
  background: linear-gradient(135deg, #ffd86b, #ff9b62);
  border: 3px solid #f3a447;
  border-radius: 24px;
  box-shadow: 0 8px 0 #d9cbaa;
}

.site-header::after {
  content: "✦  ✦  ✦";
  position: absolute;
  top: 0.8rem;
  right: 1.25rem;
  color: #fff7cf;
  font-size: 1.3rem;
  letter-spacing: 0.35rem;
}

.site-header h1 {
  max-width: 25rem;
  color: #263b2d;
  text-shadow: 2px 3px 0 #fff0a8;
}

.eyebrow {
  margin: 0 0 0.55rem;
  color: var(--accent);
  font-size: 0.76rem;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.intro {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 1.5rem;
  align-items: center;
  padding: 1.5rem;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.dino-mark {
  font-size: clamp(4rem, 13vw, 7rem);
  line-height: 1;
  transform: scaleX(-1);
}


h1 {
  font-size: clamp(2rem, 6vw, 3rem);
  line-height: 1.1;
  margin: 0;
  letter-spacing: -0.02em;
}

.tagline {
  max-width: 25rem;
  margin: 0.65rem 0 0;
  color: #4d5631;
  font-weight: 650;
}

.site-nav {
  display: flex;
  gap: 1.25rem;
  padding-top: 0.5rem;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid var(--line);
}

.site-nav a {
  color: var(--accent);
  text-decoration: none;
  font-weight: 600;
}

.site-nav a:hover,
.site-nav a:focus-visible {
  text-decoration: underline;
}

main {
  padding-top: 2rem;
  padding-bottom: 3rem;
}

section + section {
  margin-top: 2.5rem;
}

h2 {
  font-size: 1.55rem;
  margin: 0 0 0.5rem;
}

.intro h2 {
  font-size: clamp(1.8rem, 5vw, 2.5rem);
  line-height: 1.1;
}

.intro p {
  color: var(--muted);
  max-width: 34rem;
}

.button-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.7rem;
  margin-top: 0.4rem;
}

.roar-button {
  background: #668b45;
}

.roar-message {
  min-height: 1.6em;
  margin: 0.75rem 0 0;
  color: var(--accent);
  font-weight: 800;
}


code {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 0.1em 0.35em;
  font-size: 0.9em;
}

button {
  font: inherit;
  font-weight: 600;
  color: var(--bg);
  background: var(--accent);
  border: none;
  border-radius: var(--radius);
  padding: 0.65rem 1.1rem;
  cursor: pointer;
}

button:hover {
  filter: brightness(1.08);
}

/* Never remove the focus ring without putting a visible one back: it is how somebody
 * using only a keyboard can tell where they are. */
button:focus-visible,
a:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.cards {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 1rem;
  /* One column on a phone, more when there is room. Nothing to configure. */
  grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr));
}

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1.25rem 1.1rem;
  border-top: 5px solid var(--accent);
}

.card.herbivore {
  border-top-color: #668b45;
}

.card.hunter {
  border-top-color: var(--accent);
}

.card.flyer {
  border-top-color: #6d75a8;
}

.card-icon {
  display: block;
  font-size: 2rem;
  margin-bottom: 0.65rem;
}

.card p {
  font-size: 0.95rem;
}

.card strong {
  color: var(--ink);
}

.fact {
  margin: 1rem 0 0;
  padding: 0.9rem 1rem;
  color: var(--ink);
  background: color-mix(in srgb, var(--accent) 14%, var(--card));
  border-radius: 10px;
  font-weight: 600;
}

.fossils {
  padding: 1.5rem;
  background: var(--ink);
  color: var(--bg);
  border-radius: var(--radius);
}

.fossils .eyebrow {
  color: #f08a58;
}

.fossils p:not(.eyebrow) {
  color: color-mix(in srgb, var(--bg) 75%, var(--ink));
}

.fossil-list {
  list-style: none;
  display: grid;
  gap: 0.8rem;
  margin: 1.25rem 0 0;
  padding: 0;
}

.fossil-list li {
  display: grid;
  gap: 0.15rem;
  padding: 0.8rem 0;
  border-top: 1px solid color-mix(in srgb, var(--bg) 25%, transparent);
}

.fossil-list span {
  color: color-mix(in srgb, var(--bg) 70%, var(--ink));
  font-size: 0.95rem;
}

.fun-facts {
  margin-top: 1.5rem;
  padding: 1rem 1.1rem;
  color: var(--ink);
  background: var(--bg);
  border-radius: 12px;
}

.fun-facts h3 {
  margin: 0 0 0.4rem;
  color: var(--accent);
}

.fun-facts ol {
  margin: 0;
  padding-left: 1.4rem;
}

.fun-facts li + li {
  margin-top: 0.35rem;
}

.card h3 {
  margin: 0 0 0.25rem;
  font-size: 1.05rem;
}

.card p {
  margin: 0;
  color: var(--muted);
}

img {
  max-width: 100%;
  height: auto;
  border-radius: var(--radius);
}

.site-footer {
  padding-top: 1.5rem;
  padding-bottom: 3rem;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 0.9rem;
}

@media (max-width: 30rem) {
  .intro {
    grid-template-columns: 1fr;
  }

  .dino-mark {
    display: none;
  }
}

files.src/script.js:
// What happens when you click something.
//
// One interaction, on purpose: pressing the button picks a new accent colour, and
// everything using --accent changes at once because styles.css names that colour in
// exactly one place.
//
// Nothing here talks to the internet.

const FACTS = [
  "The word dinosaur means 'terrible lizard,' although dinosaurs were not actually lizards.",
  "Birds are living dinosaurs. They are the only dinosaur group still alive today.",
  "Some dinosaur fossils show feathers, including fossils of several meat-eating dinosaurs.",
  "A Triceratops had three horns and a large shield called a frill."
];

const button = document.getElementById("surprise");
const fact = document.getElementById("fact");

button.addEventListener("click", () => {
  const pick = FACTS[Math.floor(Math.random() * FACTS.length)];
  fact.textContent = pick;
});

