  padding: 0;
}

.fossil-list li {
  display: grid;
  gap: 0.15rem;
  padding: 0.8rem 0;
  border-top: 1px solid color-mix(in srgb, var(--bg) 25%, transparent);
}

.fossil-list span {
  color: color-mix(in srgb, var(--bg) 70%, var(--ink));
  font-size: 0.95rem;
}

.card h3 {
  margin: 0 0 0.25rem;
  font-size: 1.05rem;
}

.card p {
  margin: 0;
  color: var(--muted);
}

img {
  max-width: 100%;
  height: auto;
  border-radius: var(--radius);
}

.site-footer {
  padding-top: 1.5rem;
  padding-bottom: 3rem;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 0.9rem;
}

@media (max-width: 30rem) {
  .intro {
    grid-template-columns: 1fr;
  }

  .dino-mark {
    display: none;
  }
}

